import json,copy
from pathlib import Path
ROOT=Path('/home/matrix/Projects/Claude')
REF=json.loads((ROOT/'reference/bosova-topics.json').read_text())
F={'op':'forward'};L={'op':'left'};R={'op':'right'}
def rep(n,*b):return {'op':'repeat','n':n,'body':list(b)}
def wh(c,*b):return {'op':'while','cond':c,'body':list(b)}
def iff(c,t,e=()):return {'op':'if','cond':c,'then':list(t),'else':list(e)}
def mv(s):return [{'op':'move','d':d} for d in s]
def st(v,e):return {'op':'set','var':v,'expr':e}
def lv(title,prompt,hint,explanation,**k):return dict(title=title,prompt=prompt,hint=hint,explanation=explanation,**k)

A={}
A[1]=lv('Первые шаги','Доведите робота до флажка. Нажимайте на команду «вперёд» — она встанет в программу. Потом нажмите «Запустить».','До флажка четыре клетки, значит, нужно четыре команды «вперёд».','Робот — исполнитель: он выполняет команды строго по порядку, одну за другой. Такая программа называется линейной.',
  grid=['#####','S...G','#####'],blocks=['forward'],par=4,max=6,solution=[F,F,F,F])
A[2]=lv('Поворот','Коридор поворачивает. Команды «налево» и «направо» разворачивают робота на месте, но не двигают его.','Два шага вперёд, поворот направо, два шага вперёд, поворот налево и ещё шаг.','Поворот считается от самого робота: «направо» — это его правая сторона, а не правая сторона экрана.',
  grid=['S..#','##.#','##.G'],blocks=['forward','left','right'],par=7,max=10,solution=[F,F,R,F,F,L,F])
A[3]=lv('Кристаллы','Соберите оба кристалла и остановитесь на флажке. Кристалл подбирается сам, когда робот встаёт на его клетку.','Пройдите верхний ряд до конца, спуститесь по правому краю и вернитесь по нижнему ряду.','Программа получилась длинной: в ней много одинаковых команд подряд. На следующих уровнях их заменит цикл.',
  grid=['S.*.','###.','G.*.'],blocks=['forward','left','right'],par=10,max=12,solution=[F,F,F,R,F,F,R,F,F,F])
A[4]=lv('Длинный коридор','До флажка семь клеток, а блоков разрешено всего четыре. Используйте блок «повтори»: поставьте его, задайте число кнопками «+» и «−» и положите внутрь команду.','Поставьте «повтори», увеличьте число до 7 и добавьте внутрь одну команду «вперёд».','Цикл с заданным числом повторений выполняет своё тело столько раз, сколько указано. Два блока заменили семь.',
  grid=['########','S......G'],blocks=['forward','repeat'],par=2,max=4,solution=[rep(7,F)])
A[5]=lv('Лестница','Робот поднимается по лестнице. Найдите группу команд, которая повторяется на каждой ступеньке, и положите её в цикл.','Одна ступенька — это «вперёд, налево, вперёд, направо». Ступенек три.','В тело цикла можно положить несколько команд. Главное — найти повторяющийся фрагмент и убедиться, что после него робот смотрит в ту же сторону, что и до него.',
  grid=['###G','##..','#..#','S.##'],blocks=['forward','left','right','repeat'],par=5,max=7,solution=[rep(3,F,L,F,R)])
A[6]=lv('Обход по квадрату','Соберите три кристалла в углах и дойдите до флажка. Здесь пригодится цикл внутри цикла.','Сторона квадрата — «повтори 3: вперёд» и поворот направо. Таких сторон три, а потом ещё два шага до флажка.','Цикл, вложенный в другой цикл, выполняется заново при каждом повторении внешнего. Чтобы добавить команду после вложенного цикла, щёлкните по тонкой полоске под ним.',
  grid=['S..*','G##.','.##.','*..*'],blocks=['forward','left','right','repeat'],par=6,max=8,solution=[rep(3,rep(3,F),R),rep(2,F)])
A[7]=lv('Пока впереди свободно','Блока «повтори» больше нет. Зато есть цикл «пока»: он повторяет команды, пока выполняется условие.','«Пока впереди свободно: вперёд» доведёт робота до стены. Затем поверните направо и повторите тот же цикл.','Цикл с условием удобен, когда число повторений заранее неизвестно: робот сам проверяет условие перед каждым шагом.',
  grid=['S.....','#####.','#####.','#####G'],blocks=['forward','left','right','while'],conds=['free'],par=5,max=6,solution=[wh('free',F),R,wh('free',F)])
A[8]=lv('Спираль','Коридор закручивается по спирали. Вся программа помещается в четыре блока: цикл «пока не на финише», а внутри — ещё один цикл.','Внутри внешнего цикла: «пока впереди свободно: вперёд», а затем поворот направо.','Внешний цикл проверяет главное условие — достигнута ли цель. Внутренний выполняет один отрезок пути. Так короткая программа проходит длинный маршрут.',
  grid=['S....','####.','..G#.','.###.','.....'],blocks=['forward','left','right','while'],conds=['free','notgoal'],par=4,max=6,solution=[wh('notgoal',wh('free',F),R)])
A[9]=lv('Развилка: если — иначе','Добавился блок «если». Составьте программу, в которой робот на каждом шаге сам решает: идти вперёд или поворачивать.','Пока не на финише: если впереди свободно — вперёд, иначе — налево.','Ветвление выбирает одну из двух веток в зависимости от условия. Вместе с циклом получается алгоритм, который подходит для любого коридора с левыми поворотами.',
  grid=['.....','.###.','..G#.','####.','S....'],blocks=['forward','left','right','while','if'],conds=['free','wall','notgoal'],par=4,max=6,solution=[wh('notgoal',iff('free',[F],[L]))])
A[10]=lv('Правило правой руки','В этом лабиринте есть и левые, и правые повороты. Научите робота идти, «держась правой рукой за стену».','Пока не на финише: если справа свободно — направо и вперёд; иначе: если впереди свободно — вперёд, иначе — налево.','Вложенное ветвление проверяет условия по очереди. Правило правой руки — настоящий алгоритм обхода лабиринтов без замкнутых петель.',
  grid=['S.#..G','#.#.##','#...##'],blocks=['forward','left','right','while','if'],conds=['free','wall','right','left','notgoal'],par=7,max=9,solution=[wh('notgoal',iff('right',[R,F],[iff('free',[F],[L])]))])
A[11]=lv('Сбор кристаллов','Соберите шесть кристаллов. Блоков мало, поэтому длинные отрезки пути записывайте циклами.','Три отрезка: «повтори 4: вперёд», поворот направо, «повтори 2: вперёд», поворот направо, «повтори 4: вперёд».','Несколько циклов могут идти друг за другом. Каждый заменяет одинаковые команды, стоящие подряд.',
  grid=['S***.','####.','G***.'],blocks=['forward','left','right','repeat'],par=8,max=9,solution=[rep(4,F),R,rep(2,F),R,rep(4,F)])
A[12]=lv('Гребёнка','Кристаллы лежат в трёх тупиках. Действия в каждом тупике одинаковые — опишите их один раз и повторите.','Один тупик: налево, два шага вперёд, разворот (два раза направо), два шага назад, налево и два шага до следующего тупика.','Тело цикла может само содержать циклы. Важно, чтобы в конце каждого повторения робот стоял в начале следующего тупика и смотрел в ту же сторону.',
  grid=['*#*#*##','.#.#.##','S.....G'],blocks=['forward','left','right','repeat'],par=11,max=13,solution=[rep(3,L,rep(2,F),R,R,rep(2,F),L,rep(2,F))])

T={}
T[1]=lv('Команда за командой','Выполните программу: на каждую строку нажмите нужную стрелку.','Строки выполняются сверху вниз, каждая — один раз.','В линейном алгоритме команды выполняются по одной в том порядке, в каком записаны.',w=4,h=4,start=[0,0],program=mv('RRDDL'))
T[2]=lv('Два цикла','В программе два цикла подряд. Сколько раз выполнится каждая команда?','Сначала три раза вправо, только потом два раза вниз.','Тело цикла выполняется столько раз, сколько указано, и лишь затем программа переходит к следующей строке.',w=5,h=4,start=[0,0],program=[rep(3,*mv('R')),rep(2,*mv('D'))])
T[3]=lv('Ступеньки','В теле цикла две команды. Они выполняются парой.','Вправо, вниз — и так три раза: всего шесть команд.','Если в теле цикла несколько команд, они выполняются по порядку, а затем весь набор повторяется.',w=5,h=5,start=[0,0],program=[rep(3,*mv('RD'))])
T[4]=lv('Змейка','Цикл внутри цикла. Следите, какой цикл сейчас выполняется.','Один проход внешнего цикла: три раза вправо, вниз, три раза влево, вниз.','Вложенный цикл выполняется полностью при каждом повторении внешнего. Всего получилось 16 команд из шести строк.',w=4,h=5,start=[0,0],program=[rep(2,rep(3,*mv('R')),*mv('D'),rep(3,*mv('L')),*mv('D'))])
T[5]=lv('Счётчик','В программе появилась переменная n. Следите за её значением: от него зависит, когда закончится цикл.','n равно 4 и на каждом шаге уменьшается на 1. Цикл работает, пока n больше 0 — значит, четыре раза.','Переменная хранит значение, которое меняется при присваивании. Условие цикла проверяется перед каждым повторением.',w=5,h=3,start=[0,0],program=[st('n',4),{'op':'while','cond':['>','n',0],'body':mv('R')+[st('n',['-','n',1])]},*mv('D')])
T[6]=lv('Чётное — нечётное','Переменная цикла i меняется от 0 до 3. Остаток от деления на 2 показывает, чётное ли число.','i = 0 и i = 2 — чётные: вправо. i = 1 и i = 3 — нечётные: вниз.','range(0, 4) даёт числа 0, 1, 2, 3 — правая граница не входит. Операция % находит остаток от деления.',w=4,h=4,start=[0,0],program=[{'op':'for','var':'i','from':0,'to':4,'body':[{'op':'if','cond':['==',['%','i',2],0],'then':mv('R'),'else':mv('D')}]}])
T[7]=lv('Сложное условие','Сначала проверьте составное условие, затем выполните цикл while.','7 > 5 — истина, но 7 % 2 равно 1, поэтому условие с and ложно. В цикле x принимает значения 7, 6, 5.','Условие с and истинно, только когда истинны обе части. Цикл while остановился, когда x стал равен 4.',w=5,h=3,start=[0,0],program=[st('x',7),{'op':'if','cond':['and',['>','x',5],['==',['%','x',2],0]],'then':mv('U'),'else':mv('D')},{'op':'while','cond':['>','x',4],'body':mv('R')+[st('x',['-','x',1])]}])
T[8]=lv('Растущие шаги','Внутренний цикл зависит от переменной внешнего: с каждым разом шагов вправо становится больше.','При i = 1 — один шаг вправо, при i = 2 — два, при i = 3 — три. После каждой серии — шаг вниз.','Число повторений внутреннего цикла может зависеть от переменной внешнего. Всего 1 + 2 + 3 = 6 шагов вправо и 3 вниз.',w=7,h=4,start=[0,0],program=[{'op':'for','var':'i','from':1,'to':4,'body':[st('k','i'),{'op':'while','cond':['>','k',0],'body':mv('R')+[st('k',['-','k',1])]},*mv('D')]}])
T[9]=lv('Вспомогательный алгоритм','Программа вызывает вспомогательный алгоритм «уголок». При каждом вызове выполняются все его команды.','Один вызов — вправо, вправо, вниз. Вызовов три, а в самом конце — шаг влево.','Вспомогательный алгоритм описывают один раз, а вызывают по имени сколько угодно раз. Так программа становится короче и понятнее.',w=7,h=4,start=[0,0],funcs={'уголок':mv('RRD')},program=[rep(3,{'op':'call','name':'уголок'}),*mv('L')])
T[10]=lv('Сумма решает','Сначала вычислите сумму s, а потом решите, куда идти.','s = 1 + 2 + 3 + 4 = 10. Остаток от деления 10 на 3 равен 1. В цикле s принимает значения 10 и 8.','Накопление суммы — частый приём: переменная получает начальное значение, а в цикле к ней прибавляются слагаемые.',w=4,h=4,start=[0,0],program=[st('s',0),{'op':'for','var':'i','from':1,'to':5,'body':[st('s',['+','s','i'])]},{'op':'if','cond':['==',['%','s',3],1],'then':mv('RR'),'else':mv('D')},{'op':'while','cond':['>','s',6],'body':mv('D')+[st('s',['-','s',2])]}])
T[11]=lv('Загадочная последовательность','Число n меняется по правилу: чётное делится пополам, нечётное умножается на 3 и увеличивается на 1. Цикл идёт, пока n не станет равно 1.','Значения n: 12, 6, 3, 10, 5, 16, 8, 4, 2, 1. Запишите их на листке.','Вы проследили цикл с условием и ветвлением внутри. Трассировка — запись значений переменных на каждом шаге — главный способ понять чужую программу.',w=8,h=3,start=[0,0],program=[st('n',12),{'op':'while','cond':['!=','n',1],'body':[{'op':'if','cond':['==',['%','n',2],0],'then':[st('n',['//','n',2])]+mv('R'),'else':[st('n',['+',['*','n',3],1])]+mv('D')}]}])
T[12]=lv('Вложенное ветвление','Внутри ветки else стоит ещё одно ветвление. Проверяйте условия по порядку для каждого значения i.','i = 0 и 1 — вправо. i = 2 — вниз. i = 3 и 4 — влево.','Вложенное ветвление позволяет выбрать один из трёх и более вариантов: второе условие проверяется, только если первое ложно.',w=3,h=2,start=[0,0],program=[{'op':'for','var':'i','from':0,'to':5,'body':[{'op':'if','cond':['<','i',2],'then':mv('R'),'else':[{'op':'if','cond':['==','i',2],'then':mv('D'),'else':mv('L')}]}]}])

G={}
def lg(title,prompt,hint,expl,inputs,nodes,target,**k):return lv(title,prompt,hint,expl,inputs=inputs,nodes=nodes,out=nodes[-1]['id'],target=target,**k)
G[1]=lg('Два ключа','Сейф открывается (лампа горит), только если повёрнуты оба ключа: A = 1 и B = 1. Выберите подходящий элемент.','Нужен элемент, который даёт 1, только когда на обоих входах 1.','Элемент И (конъюнкция) выдаёт 1 только при двух единицах на входах.',['A','B'],[{'id':'g1','in':['A','B']}],[0,0,0,1],gates2=['and','or','xor'])
G[2]=lg('Две кнопки звонка','Звонок звенит, если нажата хотя бы одна из двух кнопок.','Нужен элемент, который даёт 0, только когда на обоих входах 0.','Элемент ИЛИ (дизъюнкция) выдаёт 1, если хотя бы на одном входе 1.',['A','B'],[{'id':'g1','in':['A','B']}],[0,1,1,1],gates2=['and','or','xor'])
G[3]=lg('Свет в коридоре','В длинном коридоре два выключателя. Лампа горит, когда они в разных положениях: щёлкнув любым, можно и включить, и выключить свет.','Нужен элемент, который даёт 1, когда входы различаются.','Исключающее ИЛИ даёт 1, только когда входы разные. Так устроены проходные выключатели.',['A','B'],[{'id':'g1','in':['A','B']}],[0,1,1,0],gates2=['and','or','xor'])
G[4]=lg('Сигнализация','Сирена включается, если датчик двери сработал (A = 1), а кнопка «Свой» не нажата (B = 0).','Сигнал B нужно перевернуть элементом НЕ, а затем объединить с A элементом И.','Схема реализует выражение A И НЕ B. Элемент НЕ (инверсия) меняет 0 на 1 и 1 на 0.',['A','B'],[{'id':'n1','in':['B']},{'id':'g1','in':['A','n1']}],[0,0,1,0])
G[5]=lg('Табло «Есть места»','На парковке два места. Табло «Есть места» горит всегда, кроме случая, когда заняты оба (A = 1 и B = 1).','Сначала определите «заняты оба», а потом переверните результат.','Получился элемент И-НЕ: НЕ (A И B). Из одних таких элементов можно собрать любую логическую схему.',['A','B'],[{'id':'g1','in':['A','B']},{'id':'n1','in':['g1']}],[1,1,1,0])
G[6]=lg('Сейф банка','Сейф открывается, если ключ повернул директор (C) и вместе с ним хотя бы один из двух заместителей (A или B).','Сначала объедините A и B, потом результат — с C.','Схема реализует выражение (A ИЛИ B) И C. Порядок действий в схеме задаётся соединением элементов, как скобками в выражении.',['A','B','C'],[{'id':'g1','in':['A','B']},{'id':'g2','in':['g1','C']}],[0,0,0,1,0,1,0,1])
G[7]=lg('Соберите исключающее ИЛИ','Готового элемента «исключающее ИЛИ» нет. Соберите его из элементов И, ИЛИ и НЕ: лампа горит, когда входы разные.','Входы разные — значит, «хотя бы один равен 1» и при этом НЕ «оба равны 1».','(A ИЛИ B) И НЕ (A И B) — это и есть исключающее ИЛИ. Сложные элементы строятся из простых.',['A','B'],[{'id':'g1','in':['A','B'],'row':0},{'id':'g2','in':['A','B'],'row':1},{'id':'n1','in':['g2'],'row':1},{'id':'g3','in':['g1','n1']}],[0,1,1,0])
G[8]=lg('Голосование','Три судьи голосуют. Решение принято (лампа горит), если «за» хотя бы двое.','Проверьте каждую пару судей элементом И, а результаты объедините.','(A И B) ИЛИ (A И C) ИЛИ (B И C) — функция большинства. Такая схема стоит в сумматоре: она вычисляет перенос в следующий разряд.',['A','B','C'],[{'id':'g1','in':['A','B'],'row':0},{'id':'g2','in':['A','C'],'row':1},{'id':'g3','in':['B','C'],'row':2},{'id':'g4','in':['g1','g2'],'row':0.5},{'id':'g5','in':['g4','g3'],'row':1.25}],[0,0,0,1,0,1,1,1])
G[9]=lg('Импликация','Соберите схему для высказывания «если A, то B». Оно ложно только в одном случае: A = 1, а B = 0.','Импликацию можно выразить так: НЕ A ИЛИ B.','A → B = НЕ A ИЛИ B. Замена импликации дизъюнкцией — одно из основных преобразований логических выражений.',['A','B'],[{'id':'n1','in':['A']},{'id':'g1','in':['n1','B']}],[1,1,0,1])
G[10]=lg('Эквивалентность','Лампа должна гореть, когда значения A и B совпадают.','«Совпадают» — это отрицание «различаются».','Эквивалентность — инверсия исключающего ИЛИ: она истинна, когда оба операнда равны.',['A','B'],[{'id':'g1','in':['A','B']},{'id':'n1','in':['g1']}],[1,0,0,1],gates2=['and','or','xor'])

P={}
def px(title,rows,show,prompt,hint,expl,**k):return lv(title,prompt,hint,expl,rows=rows,show=show,**k)
BIN='Каждая клетка рисунка хранит один бит: 1 — закрашена, 0 — пустая. Так компьютер хранит чёрно-белое изображение.'
