P[3]=px('Пришелец',['00011000','00111100','01111110','11011011','11111111','00100100','01011010','10100101'],'hex','Раскодируйте рисунок 8 × 8 по шестнадцатеричным кодам строк.','D = 1101, B = 1011, 2 = 0010, 4 = 0100, 5 = 0101, A = 1010.','На рисунок 8 × 8 в один бит на пиксель нужно 64 бита — это 8 байт, по байту на строку.')
P[9]=px('Сердце 8 × 8',['01100110','11111111','11111111','11111111','01111110','00111100','00011000','00000000'],'hex','Последний рисунок — без подсказок с весами разрядов.','6 = 0110, F = 1111, 7 = 0111, E = 1110, 3 = 0011, C = 1100, 1 = 0001, 8 = 1000.','Шестнадцатеричная запись — компактный способ записать двоичный код изображения.',weights=False)

def gr(title,nodes,edges,a,b,prompt,hint,expl):return lv(title,prompt,hint,expl,nodes=[{'id':i,'x':x,'y':y} for i,x,y in nodes],edges=edges,**{'from':a,'to':b})
