def series(title,prompt,hint,expl,**k):return lv(title,prompt,hint,expl,**k)
def task(text,answer,unit=None,tip=None,**vars):
    t={'text':text,'answer':answer,'vars':vars}
    if unit:t['unit']=unit
    if tip:t['tip']=tip
    return t
