AB=['A','B'];ABC3=['A','B','C'];NOT=lambda x:['not',x];AND=lambda a,b:['and',a,b];OR=lambda a,b:['or',a,b];IMP=lambda a,b:['->',a,b];EQ=lambda a,b:['<->',a,b]
