def tr(title,vs,expr,hint,expl):return lv(title,TP,hint,expl,vars=vs,cols=[expr])
TR={1:tr('Сначала НЕ',AB,AND('A',NOT('B')),'Сначала найдите НЕ B. Выражение истинно, только когда A = 1 и B = 0.','Инверсия выполняется раньше конъюнкции, поэтому сначала находят НЕ B.'),
 2:tr('Отрицание в скобках',AB,NOT(OR('A','B')),'A ИЛИ B ложно только при двух нулях — значит, выражение истинно только тогда.','Скобки меняют порядок действий: сначала дизъюнкция, затем инверсия.'),
 3:tr('Приоритет операций',AB,OR(AND('A','B'),NOT('A')),'Выражение истинно, если A = 0 или если обе переменные равны 1.','Порядок без скобок: сначала НЕ, затем И, затем ИЛИ.'),
 4:tr('Закон де Моргана',AB,NOT(AND('A','B')),'A И B истинно только при двух единицах. Отрицание истинно во всех остальных случаях.','НЕ (A И B) равносильно НЕ A ИЛИ НЕ B — это закон де Моргана.'),
 5:tr('Три переменные',ABC3,AND(OR('A','B'),'C'),'Нужно C = 1 и хотя бы одна единица среди A и B.','Для трёх переменных существует 2³ = 8 наборов значений.'),
 6:tr('Составное выражение',ABC3,OR(AND('A','B'),NOT('C')),'Выражение истинно, если C = 0 или если A и B обе равны 1.','Сложное выражение вычисляют по действиям: НЕ C, затем A И B, затем ИЛИ.'),
 7:tr('Импликация',AB,IMP('A','B'),'A → B ложно только при A = 1, B = 0.','Импликация ложна в единственном случае: из истины следует ложь. A → B равносильно НЕ A ИЛИ B.'),
 8:tr('В обе стороны',AB,AND(IMP('A','B'),IMP('B','A')),'Каждая импликация ложна в одном случае. Обе истинны, когда A и B равны.','(A → B) И (B → A) истинно, когда A и B равны, — это эквивалентность.'),
 9:tr('Не эквивалентны',AB,NOT(EQ('A','B')),'A ≡ B истинно, когда значения совпадают. Здесь нужно наоборот.','Отрицание эквивалентности — исключающее ИЛИ: оно истинно, когда значения различны.'),
 10:tr('Импликация с тремя переменными',ABC3,IMP(AND('A','B'),'C'),'Ложно только при A = 1, B = 1, C = 0.','Конъюнкция выполняется раньше импликации, поэтому скобки вокруг A И B не нужны.'),
 11:tr('Сложная импликация',ABC3,IMP(OR('A','B'),NOT('C')),'Ложно, когда A ИЛИ B = 1 и при этом C = 1.','Порядок действий: инверсия, конъюнкция, дизъюнкция, импликация, эквивалентность.')}
at=lambda i:['at','a',i]
def seta(i,e):return {'op':'seta','arr':'a','idx':i,'expr':e}
def fr(a,b,*body):return {'op':'for','var':'i','from':a,'to':b,'body':list(body)}
def cond(c,t,e=()):
    d={'op':'if','cond':c,'then':list(t)}
    if e:d['else']=list(e)
    return d
def ar(title,a,program,ask,prompt,hint,expl):return lv(title,prompt,hint,expl,init={'a':a},program=program,ask=ask)
