def num(text,base):return int(text,base)
def npairs(pairs,ba,bb):
    for a,b in pairs:assert num(a,ba)==num(b,bb),(a,b)
    sub={2:'₂',8:'₈',10:'',16:'₁₆'};return [(a+sub[ba],b+sub[bb]) for a,b in pairs]
