def world(id,type,title,desc,topic,levels,**k):
    w=dict(id=id,type=type,title=title,description=desc,**k)
    if topic:w['topicId']=topic
    w['levels']=[]
    for i,l in enumerate(levels):
        l=copy.deepcopy(l);w['levels'].append({'id':f'{id}-{i+1}',**l})
        # каждый второй уровень аркадных миров играется в другом жанре на тех же данных
        if type in ('calc','binary') and i in (1,3):w['levels'][-1].update(play='race',prompt='Гонка: прочитайте вопрос на табло и въезжайте в ворота с верным ответом.')
        if type=='snake' and i in (1,3):w['levels'][-1].update(play='shooter',prompt='Космический тир: сбивайте тарелки строго по порядку из правила.' if l.get('ordered') else 'Космический тир: сбивайте только те тарелки, которые подходят под правило, остальные пропускайте.')
    return w
NOTES=['Тренажёр рассчитан на несколько уроков: один мир занимает примерно 15–20 минут. Назовите ученикам мир, который нужно пройти сегодня.',
 'Отметка за мир считается по звёздам: «5» — от 80 %, «4» — от 60 %, «3» — от 33 % (один-единственный балл за каждый уровень уже даёт «3»). Непройденные уровни дают 0 звёзд.',
 'Ученик сам нажимает «Отправить отметку в журнал». Отметка за мир занимает в журнале одну строку на ученика (тема «N класс: Кодоград: игровой тренажёр · название мира») и обновляется, когда ученик улучшил результат.',
 'Прогресс хранится на школьном сервере отдельно для каждого ученика и класса: продолжить можно с любого компьютера кабинета. Перед следующим классом достаточно нажать «Сменить игрока».',
 'Кнопка «Панель учителя» видна только с учительского ноутбука. В ней — успеваемость класса по мирам, выбор задания на урок и список класса. Когда список загружен, ученики выбирают себя из него и не могут ввести другое имя.',
 'Если сервер журнала недоступен, тренажёр продолжает работать: прогресс временно хранится в браузере компьютера и переносится на сервер при следующем входе.',
 'Это учебная игра, а не защищённая контрольная: задания проверяются в браузере, а ученик может ввести чужую фамилию. Для итоговой проверки используйте обычный тест.',
 'В аркадах («Двоичный конвейер», «Защита сервера», «Турникет», «Зависшие формулы») есть таймер и три жизни: звёзды зависят от того, сколько жизней осталось. Проигранный уровень можно сразу начать заново, штрафа за это нет. Если темп для класса слишком высок, его можно замедлить полем seconds в JSON уровня — скажите, я поправлю.',
 'Во все игры можно играть с клавиатуры: под каждой игрой есть строка с клавишами. Мышь тоже работает.',
 'Звук по умолчанию выключен; ученик включает его кнопкой «Звук» вверху страницы.',
 'Наводящий вопрос бесплатный. Звёзды снижают: подсказка посильнее (−1), лишние блоки в программе робота, ошибки при исполнении программы и неверные проверки. Неудачные запуски робота не штрафуются — экспериментировать можно свободно.',
 'С учительского ноутбука все уровни открыты сразу, чтобы показать любой на проекторе. Не отправляйте пробные результаты под именем ученика.',
 'Привязка миров к параграфам — по названиям тем из справочника сайта. Сверьте с вашим календарно-тематическим планированием.']
INSTR=['Выберите мир, который назвал учитель, и проходите уровни по порядку: следующий открывается после предыдущего.',
 'За уровень дают от одной до трёх звёзд. Наводящий вопрос бесплатный, подсказка посильнее стоит одну звезду. Любой уровень можно пройти ещё раз — засчитывается лучший результат.',
 'Когда закончите, на карте миров нажмите «Отправить отметку в журнал» и дождитесь номера квитанции.',
 'Уходя, нажмите «Сменить игрока». Чтобы продолжить в другой раз, выберите тот же класс и то же имя.']
def trainer(grade,series,worlds,description,goals,story):
    s=next(x for x in REF['series'] if x['id']==series);topics=list(dict.fromkeys(w['topicId'] for w in worlds if 'topicId' in w))
    d=dict(schemaVersion=1,kind='trainer',slug=f'trainer-{grade}-kodograd',grade=grade,subject='Информатика',title='Кодоград: игровой тренажёр',description=description,durationMinutes=40,
      story=story,goals=goals,instructions=INSTR,teacherNotes=NOTES,grading={'three':33,'four':60,'five':80},
      curriculum={'provider':'bosova','seriesId':series,'topicId':topics[0],'topicIds':topics,'sourceUrl':next(t['sourceUrl'] for t in s['topics'] if t['id']==topics[0])},worlds=worlds)
    (ROOT/'drafts'/f"{d['slug']}.json").write_text(json.dumps(d,ensure_ascii=False,indent=1)+'\n')
STORY=['Добро пожаловать в Кодоград — город, где всё работает на алгоритмах, битах и логике.','В каждом районе города свои испытания. Не читайте — действуйте: программируйте робота, щёлкайте переключателями, прокладывайте маршруты.']
def pool(src,*ids):return [src[i] for i in ids]
